function classify(value) {
  if (value < 0) {
    return "neg";
  }
  if (value == 0) {
    return "zero";
  }
  return "pos";
}
console.log("edge_control_return", classify(-1), classify(0), classify(2));

let count = 0;
function bump() {
  count = count + 1;
  return true;
}
if (false && bump()) {
  count = count + 10;
}
if (true || bump()) {
  count = count + 2;
}
console.log("edge_control_short", count);

function makeCounter(start) {
  let value = start;
  function inc(step) {
    value = value + step;
    return value;
  }
  return inc(2) + inc(3);
}
console.log("edge_scope", makeCounter(5));

